"""Fair-budget Route-A benchmark and ablation runner."""
from __future__ import annotations
import argparse,csv,json,os
from config import AttributeRefinementWeights,Weights
from data import prepare_instance
from experiment_configs import core_budget,experiment_configurations
from model_common import handling_diagnostics,has_attribute_data
from solve_direct_gurobi import INSTANCES,solve_direct_gurobi
from solver_mip_alns import solve_strengthened_mip_alns

FIELDS="""instance algorithm seed threads alloc_domain valid_inequalities symmetry_breaking handling_rate_scale old_outbound_release_policy phase1_runtime alns_runtime phase3_runtime core_total_runtime refinement_runtime total_runtime phase1_ub phase1_lb phase1_gap alns_best_ub alns_improvement phase3_ub phase3_lb phase3_gap core_ub core_lb core_gap core_solution_source core_pod_spread core_weight_spread core_height_mix core_attribute_score attribute_data_available refinement_status refinement_accepted attribute_basis attribute_scope epsilon candidate_core_cost core_degradation_absolute core_degradation_relative candidate_pod_spread candidate_weight_spread candidate_height_mix candidate_attribute_score final_pod_spread final_weight_spread final_height_mix final_attribute_score root_relaxation_bound final_global_bound phase1_nodes phase3_nodes total_nodes max_solution_violation max_handling_utilization average_active_handling_utilization binding_handling_constraints number_of_active_bays""".split()
def run_one(instance,seed,cfg,total_core_time,refinement_time,threads,mip_gap):
    domain=cfg.get("domain","integer");rate=cfg.get("rate",1.0);valid=cfg.get("valid",True);symmetry=cfg.get("symmetry",False);epsilon=cfg.get("epsilon",.01);scope=cfg.get("scope","final");basis=cfg.get("basis","inventory");release=cfg.get("release","proportional");attrs=cfg.get("attributes","all");weights=Weights(attribute=AttributeRefinementWeights(4 if attrs in ("all","pod") else 0,3 if attrs in ("all","weight") else 0,10 if attrs in ("all","height") else 0));data=prepare_instance(INSTANCES[instance](),rate,release);budget=core_budget(total_core_time,cfg)
    if cfg.get("plain"):
      r=solve_direct_gurobi(data,weights,time_limit_s=total_core_time,mip_gap=mip_gap,threads=threads,seed=seed,verbose=False,alloc_domain=domain,add_valid_inequalities=valid,symmetry_breaking=symmetry);p1=r;alns={};p3={};core={"ub":r.get("ub"),"lb":r.get("lb"),"gap":r.get("gap"),"solution_source":"plain","components":r.get("components"),"feasibility_report":r.get("feasibility_report"),"solution":r.get("solution")};ref={"status":"DISABLED","accepted":False,"runtime":0};final_components=core["components"]
    else:
      r=solve_strengthened_mip_alns(data,weights,phase1_time=budget["phase1"],lns_time=budget["alns"],phase3_time=budget["phase3"],attribute_time=refinement_time,attribute_epsilon=epsilon,attribute_scope=scope,attribute_basis=basis,alloc_domain=domain,add_valid_inequalities=valid,symmetry_breaking=symmetry,seed=seed,threads=threads,mip_gap=mip_gap,enable_alns=cfg.get("alns",True),enable_proof=cfg.get("proof",True),enable_refinement=cfg.get("refine",True));p1=r.get("phase1_core_mip",{});alns=r.get("phase2_alns",{});p3=r.get("phase3_proof_mip",{});core=r.get("core_best",{});ref=r.get("attribute_refinement",{});final_components=r.get("final_solution",{}).get("components")
    core_components=core.get("components") or {};core_raw=core_components.get("raw",{});candidate=(ref.get("candidate_components") or {}).get("raw",{});final_raw=(final_components or {}).get("raw",{});diag=handling_diagnostics(data,core.get("solution")) if core.get("solution") else {};p1rt=float(p1.get("runtime",0) or 0);art=float(alns.get("runtime",0) or 0);p3rt=float(p3.get("runtime",0) or 0);rrt=float(ref.get("runtime",0) or 0)
    row={"instance":instance,"algorithm":cfg["algorithm"],"seed":seed,"threads":threads,"alloc_domain":domain,"valid_inequalities":valid,"symmetry_breaking":symmetry,"handling_rate_scale":rate,"old_outbound_release_policy":release,"phase1_runtime":p1rt,"alns_runtime":art,"phase3_runtime":p3rt,"core_total_runtime":p1rt+art+p3rt,"refinement_runtime":rrt,"total_runtime":p1rt+art+p3rt+rrt,"phase1_ub":p1.get("ub"),"phase1_lb":p1.get("lb"),"phase1_gap":p1.get("gap"),"alns_best_ub":alns.get("best_ub"),"alns_improvement":alns.get("improvement"),"phase3_ub":p3.get("ub"),"phase3_lb":p3.get("lb"),"phase3_gap":p3.get("gap"),"core_ub":core.get("ub"),"core_lb":core.get("lb"),"core_gap":core.get("gap"),"core_solution_source":core.get("solution_source"),"core_pod_spread":core_raw.get("pod_spread"),"core_weight_spread":core_raw.get("weight_spread"),"core_height_mix":core_raw.get("height_mix"),"core_attribute_score":core_components.get("attribute_score"),"attribute_data_available":has_attribute_data(data),"refinement_status":ref.get("status"),"refinement_accepted":ref.get("accepted"),"attribute_basis":basis,"attribute_scope":scope,"epsilon":epsilon,"candidate_core_cost":ref.get("candidate_core_cost"),"core_degradation_absolute":ref.get("core_degradation_absolute"),"core_degradation_relative":ref.get("core_degradation_relative"),"candidate_pod_spread":candidate.get("pod_spread"),"candidate_weight_spread":candidate.get("weight_spread"),"candidate_height_mix":candidate.get("height_mix"),"candidate_attribute_score":ref.get("candidate_attribute_score"),"final_pod_spread":final_raw.get("pod_spread"),"final_weight_spread":final_raw.get("weight_spread"),"final_height_mix":final_raw.get("height_mix"),"final_attribute_score":(final_components or {}).get("attribute_score"),"root_relaxation_bound":p1.get("root_relaxation_bound"),"final_global_bound":core.get("lb"),"phase1_nodes":p1.get("nodes"),"phase3_nodes":p3.get("nodes"),"total_nodes":float(p1.get("nodes",0) or 0)+float(p3.get("nodes",0) or 0),"max_solution_violation":(core.get("feasibility_report") or {}).get("max_violation"),"max_handling_utilization":diag.get("max_handling_utilization"),"average_active_handling_utilization":diag.get("average_active_handling_utilization"),"binding_handling_constraints":diag.get("number_of_binding_handling_constraints"),"number_of_active_bays":diag.get("number_of_active_bays")};return row
def main():
    p=argparse.ArgumentParser();p.add_argument("--instances",nargs="+",choices=INSTANCES,default=["tiny"]);p.add_argument("--seeds",nargs="+",type=int,default=[0]);p.add_argument("--total-core-time",type=float,default=20);p.add_argument("--refinement-time",type=float,default=5);p.add_argument("--threads",type=int,default=1);p.add_argument("--mip-gap",type=float,default=.03);p.add_argument("--suite",choices=("quick","full"),default="quick");p.add_argument("--output",default="experiments");a=p.parse_args();os.makedirs(a.output,exist_ok=True);rows=[run_one(i,s,c,a.total_core_time,a.refinement_time,a.threads,a.mip_gap) for i in a.instances for s in a.seeds for c in experiment_configurations(a.suite=="full")];json.dump(rows,open(os.path.join(a.output,"results.json"),"w",encoding="utf8"),indent=2);f=open(os.path.join(a.output,"results.csv"),"w",newline="",encoding="utf8");w=csv.DictWriter(f,fieldnames=FIELDS);w.writeheader();w.writerows(rows);f.close();print(f"wrote {len(rows)} rows to {a.output}")
if __name__=="__main__":main()
